fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut low: usize = 0;
    let mut high: usize = v.len();
    // Invariant: the target k is known to be in v,
    // and we maintain that k ∈ v[low..high].
    while low < high {
        let mid = low + (high - low) / 2;
        if v[mid] < k {
            // k cannot be in v[low..=mid], so drop that half
            low = mid + 1;
        } else {
            // k is ≥ v[mid], so it must be in v[mid..high]
            high = mid;
        }
    }
    // At this point low == high, and since k is guaranteed to be present,
    // v[low] == k
    low
}

